function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(5*t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30 - 10 * Math.sin(5*t));
  ctx.lineTo(W/2, H/2 + 30 + 10 * Math.sin(5*t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2);
  ctx.lineTo(W/2 - 60 + 10 * Math.sin(10*t), H/2 - 10);
  ctx.lineTo(W/2 - 60 + 10 * Math.sin(10*t), H/2 + 10);
  ctx.lineTo(W/2 - 50, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 60 - 10 * Math.sin(10*t), H/2 - 10);
  ctx.lineTo(W/2 + 60 - 10 * Math.sin(10*t), H/2 + 10);
  ctx.lineTo(W/2 + 50, H/2);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('...', W/2, H/2 + 70 + 10 * Math.sin(5*t));
  ctx.restore();
}
